    94  struct proxy_header_v2 {
    95      uint8_t sig[12];
    96      uint8_t cmd_ver;
    97      uint8_t fam;
    98      uint16_t len;
    99      union {
   100          struct {
   101              in_addr_t src_addr;
   102              in_addr_t dst_addr;
   103              uint16_t src_port;
   104              uint16_t dst_port;
   105          } ip4;
   106          struct {
   107              struct in6_addr src_addr;
   108              struct in6_addr dst_addr;
   109              uint16_t src_port;
   110              uint16_t dst_port;
   111          } ip6;
   112      } addr;
   113  };
