   119  static bool
   120  parse_ascii_port(char *port, unsigned short *out)
   121  {
   122      unsigned long parsed;
   123      char *end_ptr;
   124
   125      errno = 0;
   126      parsed = strtoul(port, &end_ptr, 10);
   127
   128      if (UNLIKELY(errno != 0))
   129          return false;
   130
   131      if (UNLIKELY(*end_ptr != '\0'))
   132          return false;
   133
   134      if (UNLIKELY((unsigned long)(unsigned short)parsed != parsed))
   135          return false;
   136
   137      *out = htons((unsigned short)parsed);
   138      return true;
   139  }
   140
   141  static char *
   142  strsep_char(char *strp, char delim)
   143  {
   144      char *ptr;
   145
   146      if (UNLIKELY(!strp))
   147          return NULL;
   148
   149      ptr = strchr(strp, delim);
   150      if (UNLIKELY(!ptr))
   151          return NULL;
   152
   153      *ptr = '\0';
   154      return ptr + 1;
   155  }
